 "command": "python3 -c "from collections import deque
rows=['0011','0111','1110','0100']; cells={(r,c) for r,row in enumerate(rows) for c,x in enumerate(row) if x=='1'}
seen=set(); comps=[]
for cell in cells:
 if cell in seen: continue
 q=[cell]; seen.add(cell); comp=[]
 while q:
  a=q.pop(); comp.append(a)
  for d in [(1,0),(-1,0),(0,1),(0,-1)]:
   b=(a[0]+d[0],a[1]+d[1])
   if b in cells and b not in seen: seen.add(b);q.append(b)
 comps.append(comp)
# count enclosed background holes by flood-fill in padded bbox
bg={(r,c) for r in range(-1,5) for c in range(-1,5)}-cells
outside=set(); q=[(-1,-1)]; outside.add(q[0])
while q:
 a=q.pop()
 for d in [(1,0),(-1,0),(0,1),(0,-1)]:
  b=(a[0]+d[0],a[1]+d[1])
  if b in bg and b not in outside:outside.add(b);q.append(b)
holes=len(bg-outside)
perim=sum(1 for r,c in cells for d in [(1,0),(-1,0),(0,1),(0,-1)] if (r+d[0],c+d[1]) not in cells)
def norm(s):
 mr=min(r for r,c in s);mc=min(c for r,c in s);return frozenset((r-mr,c-mc) for r,c in s)
def rot(s):return {(c,-r) for r,c in s}
def refl(s):return {(r,-c) for r,c in s}
print({'area':len(cells),'components_4conn':len(comps),'holes_4conn':holes,'perimeter':perim,'row_sums':[r.count('1') for r in rows],'col_sums':[sum(rows[r][c]=='1' for r in range(4)) for c in range(4)], 'dihedral_symmetries':[name for name,s in [('identity',cells),('rot90',rot(cells)),('rot180',rot(rot(cells))),('rot270',rot(rot(rot(cells)))),('mirror',refl(cells))] if norm(s)==norm(cells)]})"",
