import sqlite3,re
from collections import deque
p='/home/USER/continual-arc-baselines/.workbench/stage1/HA-hermes-luna6-high-fresh0/frozen/held-out-reference/play/users/u067/system/state/hermes/state.db'
msgs=sqlite3.connect(p).execute("select id,content from messages where session_id=? and role='user' order by id",('5da12ead-c043-4070-a252-a21a965be841',)).fetchall()
def get_grid(text,label):
 m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n((?:[0-9 ]+\n?)+)',text)
 if not m:return None
 return [[int(x) for x in line.split()] for line in m.group(3).strip().splitlines()]
def comps(g,color,conn=4):
 h,w=len(g),len(g[0]); dirs=[(-1,0),(1,0),(0,-1),(0,1)]
 if conn==8: dirs += [(-1,-1),(-1,1),(1,-1),(1,1)]
 seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c]!=color or (r,c) in seen:continue
   q=[(r,c)];seen.add((r,c)); cells=[]
   for x,y in q:
    cells.append((x,y))
    for dr,dc in dirs:
     a,b=x+dr,y+dc
     if 0<=a<h and 0<=b<w and g[a][b]==color and (a,b) not in seen:
      seen.add((a,b));q.append((a,b))
   r0=min(x for x,y in cells);r1=max(x for x,y in cells);c0=min(y for x,y in cells);c1=max(y for x,y in cells)
   crop=[[int((r,c) in cells)*color for c in range(c0,c1+1)] for r in range(r0,r1+1)]
   out.append((len(cells),(r0,r1,c0,c1),crop))
 return out
for i,text in msgs:
 if not text:continue
 for n,col in [(1,1),(2,2)]:
  g=get_grid(text,f'Demo pair {n} input')
  o=get_grid(text,f'Demo pair {n} output')
  if g and o:
   print('\nDEMO',n,'out',o)
   for conn in (4,8):
    print('conn',conn)
    for area,box,crop in comps(g,col,conn):print(area,box,crop,'EXACT',crop==o)

