from collections import deque
patterns = {
'demo1':['0011','0111','1110','0100'],
'demo2':['00020','02220','20202','02200'],
'demo3':['1000001','0101010','0011100','0111110','0000100'],
'test':['008008','888880','008008','088800','808080','888880','088800'],
}
for name, rows in patterns.items():
    w=len(rows[0]); assert all(len(r)==w for r in rows)
    pts={(r,c) for r,row in enumerate(rows) for c,x in enumerate(row) if x!='0'}
    def comps(diag):
      remaining=set(pts); n=0
      moves=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (diag or dr==0 or dc==0)]
      while remaining:
       n+=1; stack=[remaining.pop()]
       while stack:
        r,c=stack.pop()
        for dr,dc in moves:
         p=(r+dr,c+dc)
         if p in remaining: remaining.remove(p); stack.append(p)
      return n
    print(name, f'{len(rows)}x{w}', 'foreground',len(pts),'4-components',comps(False),'8-components',comps(True))

