from hermes_tools import terminal
cmd = "python3 - <<'PY'
from collections import deque
shapes = {
'd1':['0011','0111','1110','0100'],
'd2':['00020','02220','20202','02200'],
'd3':['1000001','0101010','0011100','0111110','0000100'],
'test':['008008','888880','008008','088800','808080','888880','088800']
}
for name, rows in shapes.items():
    pts={(r,c) for r,row in enumerate(rows) for c,ch in enumerate(row) if ch not in '0.'}
    H,W=len(rows),len(rows[0]);
    neigh4=[(1,0),(-1,0),(0,1),(0,-1)]
    neigh8=neigh4+[(1,1),(1,-1),(-1,1),(-1,-1)]
    def comps(ns):
      todo=set(pts); out=[]
      while todo:
        seed=todo.pop(); comp={seed}; q=[seed]
        while q:
          r,c=q.pop()
          for dr,dc in ns:
            p=(r+dr,c+dc)
            if p in todo: todo.remove(p); comp.add(p); q.append(p)
        out.append(comp)
      return sorted(map(len,out),reverse=True)
    # 4-neighbor edge perimeter; bounding box / filled bbox density
    per=sum((r+dr,c+dc) not in pts for r,c in pts for dr,dc in neigh4)
    print(name, 'dims', (H,W), 'area',len(pts),'density',round(len(pts)/(H*W),3),'perimeter',per,'4comp',comps(neigh4),'8comp',comps(neigh8),'bbox-tight', min(r for r,c in pts)==0 and max(r for r,c in pts)==H-1 and min(c for r,c in pts)==0 and max(c for r,c in pts)==W-1)
PY"
r = terminal(cmd, timeout=30)
print(r.get('output',''))
print('exit_code',r.get('exit_code'))

