    return [[int(x) for x in ln.split()] for ln in s.strip().splitlines() if re.fullmatch(r'\s*[0-9](?:\s+[0-9])*\s*',ln)]
def components(g,conn=8):
    h,w=len(g),len(g[0]); seen=set(); cs=[]
    ds=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc) and (conn==8 or abs(dr)+abs(dc)==1)]
    for r in range(h):
      for col in range(w):
       if g[r][col] and (r,col) not in seen:
        stack=[(r,col)]; seen.add((r,col)); comp=[]
        while stack:
         a,b=stack.pop(); comp.append((a,b))
         for dr,dc in ds:
          q=(a+dr,b+dc)
          if 0<=q[0]<h and 0<=q[1]<w and g[q[0]][q[1]] and q not in seen: seen.add(q); stack.append(q)
        cs.append(comp)
    return cs

def crop(g,comp):
    r0=min(r for r,c in comp);r1=max(r for r,c in comp);c0=min(c for r,c in comp);c1=max(c for r,c in comp)
    return [[g[r][c] if (r,c) in set(comp) else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
